module multicycle_multiply_ctrl #(parameter integer WIDTH=8)(input wire clk,input wire rst,input wire start,input wire[WIDTH-1:0]a,b,output reg busy,output reg done,output reg[2*WIDTH-1:0]result);localparam CW=(WIDTH<=1)?1:$clog2(WIDTH);reg[CW-1:0]iteration;reg[WIDTH-1:0]ca,cb;always@(posedge clk)if(rst)begin busy<=0;done<=0;result<=0;iteration<=0;end else begin done<=0;if(!busy&&start)begin busy<=1;iteration<=0;ca<=a;cb<=b;end else if(busy)begin if(iteration==WIDTH-2)begin result<=ca*cb;busy<=0;done<=1;end else iteration<=iteration+1;end end endmodule
